class Family:
    def __init__(self):
        self.g, self.par, self.sp, self.sib = {}, {}, {}, []

    def person(self, *xs):
        for x in xs:
            self.par.setdefault(x, set())

    def sex(self, x, s):
        self.person(x)
        assert self.g.get(x, s) == s, f"gender clash on {x}"
        self.g[x] = s

    def tell(self, a, rel, b):
        """Record 'a is the <rel> of b'."""
        self.person(a, b)
        sexes = {"father": "m", "mother": "f", "son": "m", "daughter": "f", "brother": "m", "sister": "f",
                 "husband": "m", "wife": "f", "child": None, "parent": None, "sibling": None, "spouse": None}
        if sexes[rel]:
            self.sex(a, sexes[rel])
        if rel in ("father", "mother", "parent"):
            self.par[b].add(a)
        elif rel in ("son", "daughter", "child"):
            self.par[a].add(b)
        elif rel in ("husband", "wife", "spouse"):
            self.sp[a], self.sp[b] = b, a
        else:
            self.sib.append({a, b})
        self.close()

    def close(self):
        changed = True
        while changed:
            changed = False
            # merge sibling groups that share a member
            groups = []
            for s in self.sib:
                s = set(s)
                for t in [t for t in groups if t & s]:
                    groups.remove(t)
                    s |= t
                groups.append(s)
            self.sib = groups
            for grp in groups:
                common = set().union(*(self.par[x] for x in grp))
                for x in grp:
                    if not common <= self.par[x]:
                        self.par[x] |= common
                        changed = True
            for c, ps in self.par.items():
                for p in list(ps):
                    s = self.sp.get(p)
                    if s and s not in ps:
                        ps.add(s)
                        changed = True
                if len(ps) == 2:
                    p, q = sorted(ps)
                    if self.sp.get(p) != q:
                        self.sp[p], self.sp[q] = q, p
                        changed = True
            for a, b in self.sp.items():
                if a in self.g and b not in self.g:
                    self.g[b] = "f" if self.g[a] == "m" else "m"
                    changed = True

    def siblings(self, x):
        for grp in self.sib:
            if x in grp:
                return grp - {x}
        return {y for y in self.par if y != x and self.par[x] and self.par[y] & self.par[x]}

    def base(self, x, y, rel):
        """True when 'x is the <rel> of y' is forced by the facts."""
        m, f = self.g.get(x) == "m", self.g.get(x) == "f"
        if rel in ("father", "mother"):
            return x in self.par.get(y, ()) and (m if rel == "father" else f)
        if rel in ("son", "daughter"):
            return y in self.par.get(x, ()) and (m if rel == "son" else f)
        if rel in ("husband", "wife"):
            return self.sp.get(y) == x and (m if rel == "husband" else f)
        if rel in ("brother", "sister"):
            return x in self.siblings(y) and (m if rel == "brother" else f)
        raise ValueError(rel)

    def holds(self, x, y, rel):
        """rel like "daughter's daughter": x is the daughter of (y's daughter)."""
        parts = rel.split("'s ")
        if len(parts) == 1:
            return self.base(x, y, rel)
        first, rest = parts[0], "'s ".join(parts[1:])
        return any(self.base(z, y, first) and self.holds(x, z, rest) for z in self.par if z not in (x, y))

def decode(expr, codes):
    fam = Family()
    toks = expr.split()
    for i in range(0, len(toks) - 2, 2):
        fam.tell(toks[i], codes[toks[i + 1]], toks[i + 2])
    return fam

def only_answer(fam, x, y, options):
    ok = [k for k, rels in options.items() if any(fam.holds(x, y, r) for r in rels)]
    assert len(ok) == 1, ok
    return ok[0]

# Worked example 2024-09-09_1230_R09: + sister, - father, * wife, ÷ mother; F related to C?
codes = {"+": "sister", "-": "father", "*": "wife", "÷": "mother"}
fam = decode("A + B - C ÷ D * E - F ÷ G", codes)
assert fam.holds("D", "F", "mother") and fam.g["F"] == "f"
opts = {"A": ["wife"], "B": ["daughter"], "C": ["daughter's daughter"], "D": ["mother"]}
assert only_answer(fam, "F", "C", opts) == "C"

