# 2024-09-09_0900_R23: which expression makes A the daughter of K?
codes = {"+": "mother", "-": "father", "$": "son", "%": "sister", "/": "wife", "=": "brother"}
exprs = {"A": "A + K / J - P = D", "B": "K + A / P - D % J", "C": "J % P = K + A = D", "D": "D + K = A / P - J"}
ok = [k for k, e in exprs.items() if decode(e, codes).holds("A", "K", "daughter")]
assert ok == ["B"], ok

