def only_child(fam, speaker, parent, sex):
    """'my <parent>'s only son/daughter': the speaker themself when the sex matches, else a sibling."""
    if fam.g[speaker] == sex:
        return speaker
    sib = "X_" + sex
    fam.tell(sib, "brother" if sex == "m" else "sister", speaker)
    return sib

# Constructed: pointing to a boy, Ravi says, "His mother is the only daughter of my mother."
fam = Family()
fam.sex("Ravi", "m")
fam.tell("M", "mother", "Ravi")
s = only_child(fam, "Ravi", "M", "f")          # Ravi is male, so this is his sister
fam.tell(s, "mother", "Boy"); fam.sex("Boy", "m")
opts = {"A": ["son"], "B": ["brother"], "C": ["sister's son", "brother's son"], "D": ["father's brother's son"]}
assert only_answer(fam, "Boy", "Ravi", opts) == "C"     # nephew

# Constructed: pointing to a girl, Ajay says, "She is the daughter of my father's only son."
fam = Family()
fam.sex("Ajay", "m")
fam.tell("Fa", "father", "Ajay")
s = only_child(fam, "Ajay", "Fa", "m")
assert s == "Ajay"                                # male speaker: the only son is the speaker
fam.tell("Girl", "daughter", s)
opts = {"A": ["daughter"], "B": ["sister"], "C": ["brother's daughter"], "D": ["mother"]}
assert only_answer(fam, "Girl", "Ajay", opts) == "A"

# Same sentence from a woman (Priya): her father's only son is her brother, so the girl is her niece.
fam = Family()
fam.sex("Priya", "f")
fam.tell("Fa", "father", "Priya")
s = only_child(fam, "Priya", "Fa", "m")
fam.tell("Girl", "daughter", s)
assert only_answer(fam, "Girl", "Priya", opts) == "C"
